//! Robust multi-load sampled-stress-limited level-set elasticity marquee.
//!
//! Candidate geometry is generated by simultaneous independent-load CutFEM
//! descent. Every final candidate is independently replayed under every declared
//! scenario; publication requires both the material-area bound and the worst
//! scenario's explicit sampled plane-strain von Mises limit.

use fs_cutfem::DesignBoxEdge;
use fs_topols::{
    GridSdf, GuardedSettings, OptimizeSettings, RobustAggregate, RobustLoadCase,
    RobustStressStop, SampledStressLimit, optimize_compliance_multi_load_stress_guarded,
};
use std::error::Error;
use std::fs::{File, OpenOptions};
use std::io::{BufWriter, Write};
use std::path::Path;
use std::process::ExitCode;

fn writer(path: &Path) -> std::io::Result<BufWriter<File>> {
    OpenOptions::new().write(true).create_new(true).open(path).map(BufWriter::new)
}

fn parse<T: std::str::FromStr>(args: &[String], index: usize, default: T) -> Result<T, Box<dyn Error>>
where
    T::Err: Error + 'static,
{
    match args.get(index) {
        Some(value) => Ok(value.parse()?),
        None => Ok(default),
    }
}

fn edge(value: &str) -> Result<DesignBoxEdge, Box<dyn Error>> {
    match value.trim().to_ascii_lowercase().as_str() {
        "bottom" => Ok(DesignBoxEdge::Bottom),
        "right" => Ok(DesignBoxEdge::Right),
        "top" => Ok(DesignBoxEdge::Top),
        "left" => Ok(DesignBoxEdge::Left),
        _ => Err(format!("unknown load edge {value:?}; expected bottom/right/top").into()),
    }
}

fn load_cases(path: &Path) -> Result<Vec<RobustLoadCase>, Box<dyn Error>> {
    let text = std::fs::read_to_string(path)?;
    if text.len() > 1_048_576 {
        return Err("load-case CSV exceeds 1 MiB".into());
    }
    let mut cases = Vec::new();
    for (line_index, raw) in text.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let fields: Vec<_> = line.split(',').map(str::trim).collect();
        if fields.len() != 6 {
            return Err(format!(
                "load-case line {} requires edge,start,end,fx,fy,weight",
                line_index + 1
            ).into());
        }
        cases.push(RobustLoadCase::new(
            edge(fields[0])?,
            fields[1].parse()?,
            fields[2].parse()?,
            [fields[3].parse()?, fields[4].parse()?],
            fields[5].parse()?,
        )?);
        if cases.len() > 64 {
            return Err("at most 64 robust load cases are admitted".into());
        }
    }
    if cases.is_empty() {
        return Err("load-case CSV contains no scenarios".into());
    }
    if !cases.iter().any(|case| case.weight() > 0.0) {
        return Err("at least one robust load case must have positive objective weight".into());
    }
    Ok(cases)
}

fn numbers(values: &[f64]) -> String {
    let body = values.iter().map(|value| format!("{value:.17e}")).collect::<Vec<_>>().join(",");
    format!("[{body}]")
}

fn counts(values: &[usize]) -> String {
    let body = values.iter().map(usize::to_string).collect::<Vec<_>>().join(",");
    format!("[{body}]")
}

fn locations(values: &[[f64; 2]]) -> String {
    let body = values.iter().map(|point| format!("[{:.17e},{:.17e}]", point[0], point[1]))
        .collect::<Vec<_>>().join(",");
    format!("[{body}]")
}

fn escaped(value: &str) -> String {
    format!("\"{}\"", value.replace('\\', "\\\\").replace('"', "\\\""))
}

fn run() -> Result<u8, Box<dyn Error>> {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.len() < 3 || args.len() > 9 {
        return Err(
            "usage: fs-marquee-elasticity-robust-stress OUTPUT_DIR LOAD_CASES.csv MAX_SAMPLED_VON_MISES [LEVEL=4] [ITERATIONS=12] [VOLFRAC=0.45] [MAX_CANDIDATES=5] [AGGREGATE=worst] [ABS_STRESS_TOL=0]"
                .into(),
        );
    }
    let output_dir = Path::new(&args[0]);
    if output_dir.try_exists()? {
        return Err("output directory already exists; refusing to overwrite it".into());
    }
    let cases = load_cases(Path::new(&args[1]))?;
    let stress_limit = SampledStressLimit::new(args[2].parse()?, parse(&args, 8, 0.0)?)?;
    let level: u32 = parse(&args, 3, 4)?;
    let iterations: usize = parse(&args, 4, 12)?;
    let volfrac: f64 = parse(&args, 5, 0.45)?;
    let max_candidates: usize = parse(&args, 6, 5)?;
    let aggregate = match args.get(7).map(String::as_str).unwrap_or("worst") {
        "sum" | "weighted-sum" => RobustAggregate::WeightedSum,
        "worst" | "worst-weighted" => RobustAggregate::WorstWeightedCase,
        other => return Err(format!("unknown AGGREGATE {other:?}; expected sum or worst").into()),
    };
    if !(2..=7).contains(&level) {
        return Err("LEVEL must lie in [2, 7] for this bounded executable".into());
    }
    if iterations == 0 || iterations > 200 {
        return Err("ITERATIONS must lie in [1, 200]".into());
    }
    if !(volfrac.is_finite() && volfrac > 0.0 && volfrac <= 1.0) {
        return Err("VOLFRAC must lie in (0, 1]".into());
    }
    if !(1..=16).contains(&max_candidates) {
        return Err("MAX_CANDIDATES must lie in [1, 16]".into());
    }

    let n = 1usize << level;
    let mut phi = GridSdf::from_fn(n, &|_, y| (y - 0.5).abs() - 0.42);
    let settings = OptimizeSettings {
        level,
        volfrac,
        iterations,
        move_cells: 0.35,
        nucleation_period: 4,
        hole_radius_cells: 1.5,
        ..OptimizeSettings::default()
    };
    let guarded = GuardedSettings {
        max_candidates,
        contraction: 0.5,
        volume_tolerance: 0.01,
        min_relative_improvement: 0.0,
    };
    let report = optimize_compliance_multi_load_stress_guarded(
        &mut phi, &cases, settings, guarded, aggregate, stress_limit,
    )?;

    std::fs::create_dir(output_dir)?;
    let mut candidates = writer(&output_dir.join("candidates.jsonl"))?;
    for candidate in &report.candidates {
        let evaluation = candidate.evaluation.as_ref().map_or_else(
            || "null".to_string(),
            |state| format!(
                "{{\"objective\":{:.17e},\"weighted_sum_compliance\":{:.17e},\"worst_weighted_compliance\":{:.17e},\"case_compliances\":{},\"case_sampled_max_von_mises\":{},\"case_max_locations\":{},\"case_sample_counts\":{},\"worst_sampled_von_mises\":{:.17e},\"worst_stress_case\":{},\"volume\":{:.17e},\"snapshot\":\"{:#018x}\"}}",
                state.objective,
                state.weighted_sum_compliance,
                state.worst_weighted_compliance,
                numbers(&state.case_compliances),
                numbers(&state.case_sampled_max_von_mises),
                locations(&state.case_max_locations),
                counts(&state.case_sample_counts),
                state.worst_sampled_von_mises,
                state.worst_stress_case,
                state.volume,
                state.snapshot,
            ),
        );
        let refusal = candidate.refusal.as_deref().map_or_else(|| "null".to_string(), escaped);
        writeln!(
            candidates,
            "{{\"index\":{},\"move_cells\":{:.17e},\"volume_feasible\":{},\"stress_feasible\":{},\"improvement_gate\":{},\"robust_stress_evaluation\":{},\"refusal\":{}}}",
            candidate.index,
            candidate.move_cells,
            candidate.volume_feasible,
            candidate.stress_feasible,
            candidate.improvement_gate,
            evaluation,
            refusal,
        )?;
    }
    candidates.flush()?;

    let (status, exit) = match report.stop {
        RobustStressStop::Accepted => ("accepted", 0),
        RobustStressStop::NoConstraintFeasibleCandidate => ("no_constraint_feasible_candidate", 10),
        RobustStressStop::NoImprovingCandidate => ("no_improving_candidate", 11),
        RobustStressStop::AllCandidatesRefused => ("all_candidates_refused", 12),
    };
    let aggregate_name = match aggregate {
        RobustAggregate::WeightedSum => "weighted_sum",
        RobustAggregate::WorstWeightedCase => "worst_weighted_case",
    };
    let accepted = report.accepted.as_ref().map_or_else(
        || "null".to_string(),
        |state| format!(
            "{{\"objective\":{:.17e},\"case_compliances\":{},\"case_sampled_max_von_mises\":{},\"case_max_locations\":{},\"case_sample_counts\":{},\"worst_sampled_von_mises\":{:.17e},\"worst_stress_case\":{},\"volume\":{:.17e},\"snapshot\":\"{:#018x}\"}}",
            state.objective,
            numbers(&state.case_compliances),
            numbers(&state.case_sampled_max_von_mises),
            locations(&state.case_max_locations),
            counts(&state.case_sample_counts),
            state.worst_sampled_von_mises,
            state.worst_stress_case,
            state.volume,
            state.snapshot,
        ),
    );
    let summary = format!(
        "{{\"model\":\"normalized_unit_square_plane_strain_robust_stress_cantilever\",\"authority\":\"estimated\",\"status\":\"{status}\",\"aggregate\":\"{aggregate_name}\",\"load_cases\":{},\"level\":{level},\"iterations\":{iterations},\"volume_limit\":{volfrac:.17e},\"sampled_von_mises_limit\":{:.17e},\"sampled_von_mises_tolerance\":{:.17e},\"candidate_budget\":{max_candidates},\"baseline\":{{\"objective\":{:.17e},\"case_compliances\":{},\"case_sampled_max_von_mises\":{},\"case_max_locations\":{},\"case_sample_counts\":{},\"worst_sampled_von_mises\":{:.17e},\"worst_stress_case\":{},\"volume\":{:.17e},\"snapshot\":\"{:#018x}\"}},\"accepted_move_cells\":{},\"accepted\":{},\"claims\":{{\"simultaneous_multiload_shape_gradient\":true,\"stress_scope\":\"deterministic_samples_all_declared_scenarios\",\"continuous_max_stress\":false,\"stress_adjoint_kkt\":false,\"physical_validation\":false,\"global_optimum\":false,\"three_dimensional\":false}}}}",
        cases.len(),
        report.limit.max_von_mises,
        report.limit.absolute_tolerance,
        report.baseline.objective,
        numbers(&report.baseline.case_compliances),
        numbers(&report.baseline.case_sampled_max_von_mises),
        locations(&report.baseline.case_max_locations),
        counts(&report.baseline.case_sample_counts),
        report.baseline.worst_sampled_von_mises,
        report.baseline.worst_stress_case,
        report.baseline.volume,
        report.baseline.snapshot,
        report.accepted_move_cells.map_or_else(|| "null".to_string(), |value| format!("{value:.17e}")),
        accepted,
    );
    let mut summary_file = writer(&output_dir.join("summary.json"))?;
    writeln!(summary_file, "{summary}")?;
    summary_file.flush()?;

    if report.accepted.is_some() {
        let mut field = writer(&output_dir.join("level-set.csv"))?;
        writeln!(field, "x_normalized,y_normalized,phi_normalized")?;
        for j in 0..=n {
            for i in 0..=n {
                let [x, y] = phi.pos(i, j);
                writeln!(field, "{x:.17e},{y:.17e},{:.17e}", phi.node(i, j))?;
            }
        }
        field.flush()?;
        if let Some(trajectory) = report.trajectory.as_ref() {
            let mut trace = writer(&output_dir.join("trajectory.jsonl"))?;
            for row in &trajectory.rows {
                writeln!(trace, "{row}")?;
            }
            trace.flush()?;
        }
    }

    println!("{summary}");
    Ok(exit)
}

fn main() -> ExitCode {
    match run() {
        Ok(code) => ExitCode::from(code),
        Err(error) => {
            eprintln!("fs-marquee-elasticity-robust-stress: {error}");
            ExitCode::FAILURE
        }
    }
}
